<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>管理员登录 - 森码云</title>
<style>body{font-family:-apple-system,BlinkMacSystemFont,sans-serif;background:linear-gradient(135deg,#0F172A,#1E293B);min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;color:#fff}.c{max-width:400px;width:100%}.card{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:24px;padding:48px;backdrop-filter:blur(10px)}.h{text-align:center;margin-bottom:32px}.h svg{width:64px;height:64px;margin:0 auto 20px}.h h1{font-size:24px;font-weight:700}.h p{font-size:14px;color:rgba(255,255,255,.6)}.fg{margin-bottom:16px}.fg label{display:block;font-size:14px;color:rgba(255,255,255,.8);margin-bottom:8px}.fg input{width:100%;padding:14px 16px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:12px;color:#fff;font-size:15px;outline:none}.fg input:focus{border-color:#2563EB}.btn{width:100%;padding:14px;background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;border:none;border-radius:12px;font-size:16px;font-weight:600;cursor:pointer}.btn:hover{transform:translateY(-2px);box-shadow:0 10px 20px rgba(37,99,235,.3)}</style></head>
<body><div class="c"><div class="card"><div class="h"><svg viewBox="0 0 40 40"><rect width="40" height="40" rx="8" fill="url(#g)"/><path d="M20 10c-5.5 0-10 4.5-10 10s4.5 10 10 10 10-4.5 10-10-4.5-10-10-10zm0 18c-4.4 0-8-3.6-8-8s3.6-8 8-8 8 3.6 8 8-3.6 8-8 8z" fill="white"/><defs><linearGradient id="g"><stop offset="0%" stop-color="#2563EB"/><stop offset="100%" stop-color="#7C3AED"/></linearGradient></defs></svg><h1>管理员登录</h1><p>森码云实人认证系统</p></div>
<form id="f"><div class="fg"><label>用户名</label><input type="text" id="username" placeholder="用户名" required></div><div class="fg"><label>密码</label><input type="password" id="password" placeholder="密码" required></div><button type="submit" class="btn">登录</button></form></div></div>
<script>document.getElementById('f').addEventListener('submit',function(e){e.preventDefault();fetch('/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:document.getElementById('username').value,password:document.getElementById('password').value})}).then(r=>r.json()).then(d=>{if(d.code===200){location.href='/admin/dashboard';}else{alert(d.data.message||'登录失败');}}).catch(()=>alert('登录失败'));});</script>
</body></html>